import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百一十章 贪求不是这样生起的","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/110第一百一十章 贪求不是这样生起的.md","filePath":"meditation/巴利文大藏经/110第一百一十章 贪求不是这样生起的.md"}'),o={name:"meditation/巴利文大藏经/110第一百一十章 贪求不是这样生起的.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百一十章-贪求不是这样生起的" tabindex="-1">第一百一十章 贪求不是这样生起的 <a class="header-anchor" href="#第一百一十章-贪求不是这样生起的" aria-label="Permalink to &quot;第一百一十章 贪求不是这样生起的&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部14相应8经/非种种遍求经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，以种种界（界解释，见第一百零八章）为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求。弟子们，你们要注意，不要弄颠倒了，以种种贪求为前提条件不能生起种种渴爱、热爱，以种种渴爱、热爱为前提条件不能生起种种欲望，以种种欲望为前提条件不能生起种种集中专注的念想、思想，以种种集中专注的念想、思想为前提条件不能生起种种念想，以种种念想为前提条件不能生起种种界。</p><p>弟子们，什么是种种界呢？就是：色界、声界、气味界、味道界、所触界、法界（色界、声界、气味界、味道界、所触界、法界解释，见第一百零八章），这些就被称为种种界。</p><p>弟子们，什么是以种种界为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求呢？</p><p>什么是以种种贪求为前提条件不能生起种种渴爱、热爱，以种种渴爱、热爱为前提条件不能生起种种欲望，以种种欲望为前提条件不能生起种种集中专注的念想、思想，以种种集中专注的念想、思想为前提条件不能生起种种念想，以种种念想为前提条件不能生起种种界呢？就是：以色界为前提条件生起对物质事物的种种念想，以对物质事物的种种念想为前提条件就会集中专注某种由物质事物生起的念想、思想。以种种集中专注某种由物质事物生起的念想、思想为前提条件就会对物质事物生起种种的欲望，以对物质事物生起的种种欲望为前提条件就会对物质事物生起种种的渴爱、热爱，以对物质事物的种种渴爱、热爱为前提条件就会生起对物质事物的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对物质事物的种种贪求为前提条件不能生起对物质事物的种种渴爱、热爱，以对物质事物的种种渴爱、热爱为前提条件不能生起对物质事物的种种欲望，以对物质事物的种种欲望为前提条件不能生起种种集中专注某种由物质事物生起的念想、思想，以种种集中专注某种由物质事物生起的念想、思想为前提条件不能生起对物质事物的种种念想，以对物质事物的种种念想为前提条件不能生起色界。</p><p>以声界为前提条件生起对声音的种种念想，以对声音的种种念想为前提条件就会集中专注某种由声音生起的念想、思想。以种种集中专注某种由声音生起的念想、思想为前提条件就会对声音生起种种的欲望，以对声音生起的种种欲望为前提条件就会对声音生起种种的渴爱、热爱，以对声音的种种渴爱、热爱为前提条件就会生起对声音的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对声音的种种贪求为前提条件不能生起对声音的种种渴爱、热爱，以对声音的种种渴爱、热爱为前提条件不能生起对声音的种种欲望，以对声音的种种欲望为前提条件不能生起种种集中专注某种由声音生起的念想、思想，以种种集中专注某种由声音生起的念想、思想为前提条件不能生起对声音的种种念想，以对声音的种种念想为前提条件不能生起声界。</p><p>以气味界为前提条件生起对气味的种种念想，以对气味的种种念想为前提条件就会集中专注某种由气味生起的念想、思想。以种种集中专注某种由气味生起的念想、思想为前提条件就会对气味生起种种的欲望，以对气味生起的种种欲望为前提条件就会对气味生起种种的渴爱、热爱，以对气味的种种渴爱、热爱为前提条件就会生起对气味的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对气味的种种贪求为前提条件不能生起对气味的种种渴爱、热爱，以对气味的种种渴爱、热爱为前提条件不能生起对气味的种种欲望，以对气味的种种欲望为前提条件不能生起种种集中专注某种由气味生起的念想、思想，以种种集中专注某种由气味生起的念想、思想为前提条件不能生起对气味的种种念想，以对气味的种种念想为前提条件不能生起气味界。</p><p>以味道界为前提条件生起对味道的种种念想，以对味道的种种念想为前提条件就会集中专注某种由味道生起的念想、思想。以种种集中专注某种由味道生起的念想、思想为前提条件就会对味道生起种种的欲望，以对味道生起的种种欲望为前提条件就会对味道生起种种的渴爱、热爱，以对味道的种种渴爱、热爱为前提条件就会生起对味道的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对味道的种种贪求为前提条件不能生起对味道的种种渴爱、热爱，以对味道的种种渴爱、热爱为前提条件不能生起对味道的种种欲望，以对味道的种种欲望为前提条件不能生起种种集中专注某种由味道生起的念想、思想，以种种集中专注某种由味道生起的念想、思想为前提条件不能生起对味道的种种念想，以对味道的种种念想为前提条件不能生起味道界。</p><p>以所触界为前提条件生起对触觉、环境（冷热、舒适等等特性）的种种念想，以对触觉、环境（冷热、舒适等等特性）的种种念想为前提条件就会集中专注某种由触觉、环境生起的念想、思想。以种种集中专注某种由触觉、环境生起的念想、思想为前提条件就会对触觉、环境生起种种的欲望，以对触觉、环境生起的种种欲望为前提条件就会对触觉、环境生起种种的渴爱、热爱，以对触觉、环境的种种渴爱、热爱为前提条件就会生起对触觉、环境的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对触觉、环境的种种贪求为前提条件不能生起对触觉、环境的种种渴爱、热爱，以对触觉、环境的种种渴爱、热爱为前提条件不能生起对触觉、环境的种种欲望，以对触觉、环境的种种欲望为前提条件不能生起种种集中专注某种由触觉、环境生起的念想、思想，以种种集中专注某种由触觉、环境生起的念想、思想为前提条件不能生起对触觉、环境的种种念想，以对触觉、环境的种种念想为前提条件不能生起所触界。</p><p>以法界为前提条件生起对物质事物、精神思想的种种念想，以对物质事物、精神思想的种种念想为前提条件就会集中专注某种由物质事物、精神思想生起的念想、思想。以种种集中专注某种由物质事物、精神思想生起的念想、思想为前提条件就会对物质事物、精神思想生起种种的欲望，以对物质事物、精神思想生起的种种欲望为前提条件就会对物质事物、精神思想生起种种的渴爱、热爱，以对物质事物、精神思想的种种渴爱、热爱为前提条件就会生起对物质事物、精神思想的种种贪求。</p><p>弟子们，要注意，不要弄颠倒了，以对物质事物、精神思想的种种贪求为前提条件不能生起对物质事物、精神思想的种种渴爱、热爱，以对物质事物、精神思想的种种渴爱、热爱为前提条件不能生起对物质事物、精神思想的种种欲望，以对物质事物、精神思想的种种欲望为前提条件不能生起种种集中专注某种由物质事物、精神思想生起的念想、思想，以种种集中专注某种由物质事物、精神思想生起的念想、思想为前提条件不能生起对物质事物、精神思想的种种念想，以对物质事物、精神思想的种种念想为前提条件不能生起法界。</p><p>弟子们，这就是以种种界为前提条件生起种种念想，以种种念想为前提条件就会集中专注某种念想、思想。以种种集中专注的念想、思想为前提条件就会生起种种欲望，以种种欲望为前提条件就会生起种种渴爱、热爱，以种种渴爱、热爱为前提条件就会生起种种贪求的法义。</p><p>这就是以种种贪求为前提条件不能生起种种渴爱、热爱，以种种渴爱、热爱为前提条件不能生起种种欲望，以种种欲望为前提条件不能生起种种集中专注的念想、思想，以种种集中专注的念想、思想为前提条件不能生起种种念想，以种种念想为前提条件不能生起种种界的法义。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',21)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
